# Search common geometric alignment + simple Boolean rules for demo2 output (Y3 / Y7), using roll offsets and rotations.
for targetname,target in [('Y3',Y),('Y7',~Y)]:
 best=[]
 for source_name,src in [('A',A),('B',B)]:
  for rot in range(4):
   for flip in [False,True]:
    zz=np.rot90(src,rot)
    if flip: zz=np.fliplr(zz)
    if zz.shape!=(8,8): continue
    for dr in range(-2,3):
     for dc in range(-2,3):
      sh=np.roll(zz,(dr,dc),(0,1))
      # basic truth functions one/two vars
      for name,f in [('x',lambda x,y:x),('~x',lambda x,y:~x),('y',lambda x,y:y),('~y',lambda x,y:~y),('and',lambda x,y:x&y),('or',lambda x,y:x|y),('xor',lambda x,y:x^y),('x&~y',lambda x,y:x&~y),('~x&y',lambda x,y:~x&y),('~x&~y',lambda x,y:~x&~y)]:
       for other_name,other in [('origA',A),('origB',B)]:
        # src role x and other y (includes possibly duplicated vars)
        pred=f(sh,other)
        score=int(np.sum(target==pred))
        if score>=55: best.append((score,targetname,source_name,rot,flip,dr,dc,name,other_name))
 print(sorted(best,reverse=True)[:25])
